export function antzThemeOptions({ mode = 'light', contrast = 'standard' } = {}) {
  if (mode === 'dark') return contrast === 'high' ? antzDarkHighContrast : antzDark;
  return contrast === 'high' ? antzLightHighContrast : antzLight;
}
